Read a file line by line
```cpp
#include <fstream>
#include <iostream>

int main(int argc, char **argv) {
    std::ifstream input(argv[1]);
    if (!input.is_open())
        std::perror("is_open() returned false. error state");
    int xp, xo;
    int yp, yo;
    double n;
    input >> xp >> xo;
    input >> yp >> yo;
    input >> n;
}
```

